css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .body { position: absolute; left: 14%; bottom: 20%; width: 72%; height: 38%; background: linear-gradient(#94a3b8, #475569); border-radius: 8px 8px 10px 10px; z-index: 2; }
.loader .body::after { content: ''; position: absolute; bottom: 22%; left: 12%; width: 30%; height: 14%; border-radius: 3px; background: var(--accent-2); box-shadow: 0 0 calc(var(--loader-size) * .06) var(--accent-2); }
.loader .paper { position: absolute; left: 28%; bottom: 57%; width: 44%; height: 0; background: #fff; border: 1px solid #cbd5e1; overflow: hidden; animation: print calc(var(--loader-speed) * 2.4) ease-in-out infinite; }
.loader .paper::before { content: ''; position: absolute; inset: 14% 12%; background: repeating-linear-gradient(var(--accent) 0 12%, transparent 12% 30%); }
@keyframes print { 0% { height: 0; } 45%, 100% { height: 46%; } }
